+/// Balances rolled up to the first `depth` levels of the account hierarchy, by name.
+/// With depth 2, `expenses:food:groceries` and `expenses:food:dining` both count toward
+/// `expenses:food`. Accounts shallower than `depth` keep their own name. Accounts whose roll-up
+/// is zero are left out.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth starts at 1");
+    let mut out: BTreeMap<String, Amount> = BTreeMap::new();
+    for (account, amount) in ledger.balances() {
+        let key: Vec<&str> = account.split(':').take(depth).collect();
+        *out.entry(key.join(":")).or_default() += amount;
+    }
+    out.into_iter().filter(|(_, a)| *a != Amount::ZERO).collect()
+}
+
